from flask import Flask, jsonify, request

from ghz_circuit import _run_round
from session_store import SessionStore


app = Flask(__name__)
store = SessionStore()

FLAG = "<server-side flag string>"

_VALID_BASIS = frozenset("ZXY")
_MIN_SHOTS = 1
_MAX_SHOTS = 5
_STATES = 8
_ROUNDS_PER_STATE = 6
_BITS_PER_STATE = 5


def _pack_secrets(ground_truth):
    bits = 0
    for k, (s_vec, p) in enumerate(ground_truth):
        offset = k * _BITS_PER_STATE
        for j, sj in enumerate(s_vec):
            if sj:
                bits |= 1 << (offset + j)
        if p:
            bits |= 1 << (offset + 4)
    return bits


def _err(code, status):
    return jsonify({"error": code}), status


@app.route("/begin_session", methods=["POST"])
def begin_session():
    session = store.create()
    return jsonify({"session_id": session.session_id, "states_count": _STATES}), 200


@app.route("/measure", methods=["POST"])
def measure():
    data = request.get_json(silent=True) or {}
    session_id = data.get("session_id")
    state = data.get("state")
    round_num = data.get("round")
    basis = data.get("basis")
    shots = data.get("shots")

    if not isinstance(session_id, str):
        return _err("SESSION_NOT_FOUND", 404)
    try:
        session = store.get(session_id)
    except KeyError:
        return _err("SESSION_NOT_FOUND", 404)

    if isinstance(state, bool) or not isinstance(state, int) or not (1 <= state <= _STATES):
        return _err("BAD_REQUEST", 400)
    if isinstance(round_num, bool) or not isinstance(round_num, int) or not (1 <= round_num <= _ROUNDS_PER_STATE):
        return _err("BAD_REQUEST", 400)
    if not isinstance(basis, str) or len(basis) != 5 or not all(c in _VALID_BASIS for c in basis):
        return _err("INVALID_BASIS", 400)
    if isinstance(shots, bool) or not isinstance(shots, int) or not (_MIN_SHOTS <= shots <= _MAX_SHOTS):
        return _err("BAD_REQUEST", 400)

    try:
        round_index = session.consume_round(state)
    except ValueError:
        return _err("STATE_EXHAUSTED", 429)

    s_vec, p = session.ground_truth[state - 1]
    outcomes = _run_round(s_vec, p, basis, shots, state)

    return jsonify({
        "outcomes": outcomes,
        "state_index": state,
        "round_index": round_index,
    }), 200


@app.route("/submit", methods=["POST"])
def submit():
    data = request.get_json(silent=True) or {}
    session_id = data.get("session_id")
    secret_bits = data.get("secret_bits")

    if not isinstance(session_id, str):
        return _err("SESSION_NOT_FOUND", 404)
    try:
        session = store.get(session_id)
    except KeyError:
        return _err("SESSION_NOT_FOUND", 404)

    if session.is_rate_limited():
        return _err("RATE_LIMITED", 429)
    session.record_submit()

    if not isinstance(secret_bits, str) or len(secret_bits) != 10:
        return jsonify({"verdict": "incorrect", "flag": None}), 200
    try:
        submitted = int(secret_bits, 16)
    except ValueError:
        return jsonify({"verdict": "incorrect", "flag": None}), 200

    ground_truth_int = _pack_secrets(session.ground_truth)
    if submitted == ground_truth_int:
        return jsonify({"verdict": "correct", "flag": FLAG}), 200

    return jsonify({"verdict": "incorrect", "flag": None}), 200


@app.route("/health", methods=["GET"])
def health():
    return jsonify({"ok": True}), 200


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=1337, debug=False)

